#include "darwin_adapter.h"
#include "darwin_observer.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static darwin_observer_t observer;
static void print_help(void) { puts("darwin-shell commands:\n  boot | reboot | shutdown\n  ps [-axo] | top [-o cpu|mem]\n  sysctl -a | sysctl <oid> | kextstat\n  launchctl list | print <label> | start <label> | stop <label>\n  mach ports | mach send <port> <message>\n  ioreg [-l] | iokit tree\n  dmesg | log show [--last boot] [--predicate <subsystem>]\n  spawn <name> | kill <pid>\n  hostname | pwd | whoami | ls [path] | help | exit"); }
static char *next_token(char **cursor) { char *p=*cursor;while(*p==' '||*p=='\t')++p;if(!*p||*p=='\n'){*cursor=p;return NULL;}char*start=p;while(*p&&*p!=' '&&*p!='\t'&&*p!='\n')++p;if(*p)*p++='\0';*cursor=p;return start; }
static void print_sysctl_all(void) { puts("kern.ostype: Darwin\nkern.osrelease: 27.0.0\nkern.osrevision: 1\nkern.version: Darwin Kernel Version 27.0.0: root:xnu-prototype\nkern.hostname: darwin-prototype\nkern.boottime: { sec = 0, usec = 0 }\nkern.maxproc: 32\nkern.maxfiles: 10240\nkern.ipc.max_kernel_pipes: 512\nkern.ipc.mach_ports: 64\nkern.vm.pagesize: 4096\nkern.osproductversion: 27.0.0\nhw.machine: portable\nhw.model: DarwinPrototype1,1\nhw.ncpu: 4\nhw.memsize: 4294967296\nhw.byteorder: 1234\nhw.optional_64bit_ops: 1\nvfs.rootfs: virtual-apfs\nvfs.generic.maxtimes: 1"); }
static void print_kextstat(void) { puts("Index Refs Address        Size       Name (Version)");puts("    0    1 0x00000000     0x1000     com.apple.kernel (27.0.0)");puts("    1    1 0x00001000     0x0800     com.apple.iokit (1.0)");puts("    2    2 0x00001800     0x0600     com.apple.driver.IOPlatformExpert (1.0)");puts("    3    1 0x00001e00     0x0400     com.apple.filesystems.apfs (1.0)"); }
int main(void) { char line[512];darwin_observer_init(&observer);puts("Darwin Shell 27.0.0 (simulated user space)");print_help();for(;;){fputs("darwin% ",stdout);fflush(stdout);if(!fgets(line,sizeof(line),stdin))break;char*cursor=line,*command=next_token(&cursor),*arg1=next_token(&cursor),*arg2=next_token(&cursor);if(!command)continue;if(!strcmp(command,"exit")||!strcmp(command,"quit"))break;if(!strcmp(command,"help")){print_help();continue;}if(!strcmp(command,"boot")){darwin_observer_boot(&observer);puts("boot complete");continue;}if(!strcmp(command,"reboot")){darwin_observer_shutdown(&observer);darwin_observer_boot(&observer);puts("reboot complete");continue;}if(!strcmp(command,"shutdown")){darwin_observer_shutdown(&observer);puts("shutdown requested");continue;}if(!strcmp(command,"ps")){darwin_print_processes(&observer,0,"cpu");continue;}if(!strcmp(command,"top")){darwin_print_processes(&observer,1,(arg1&&(!strcmp(arg1,"-o")||!strcmp(arg1,"-sort"))&&arg2)?arg2:"cpu");continue;}if(!strcmp(command,"sysctl")){if(!arg1||!strcmp(arg1,"-a"))print_sysctl_all();else if(!strcmp(arg1,"kern.ostype"))puts("Darwin");else if(!strcmp(arg1,"kern.osrelease"))puts("27.0.0");else if(!strcmp(arg1,"hw.ncpu"))puts("4");else puts("sysctl: unknown oid");continue;}if(!strcmp(command,"kextstat")){print_kextstat();continue;}if(!strcmp(command,"launchctl")){if(!arg1||!strcmp(arg1,"list"))darwin_print_services(&observer);else if(!strcmp(arg1,"print")&&arg2){if(darwin_service_print(&observer,arg2))puts("launchctl: service not found");}else if((!strcmp(arg1,"start")||!strcmp(arg1,"stop"))&&arg2){if(darwin_service_set_state(&observer,arg2,!strcmp(arg1,"start")))puts("launchctl: service not found");else puts(!strcmp(arg1,"start")?"service started":"service stopped");}else puts("usage: launchctl list|print|start|stop <label>");continue;}if(!strcmp(command,"mach")){if(arg1&&!strcmp(arg1,"ports"))darwin_print_ports(&observer);else if(arg1&&!strcmp(arg1,"send")&&arg2){char*message=next_token(&cursor);darwin_send_message(&observer,atoi(arg2),message?message:"shell message");puts("message sent");}continue;}if(!strcmp(command,"iokit")||!strcmp(command,"ioreg")){darwin_print_devices(&observer);continue;}if(!strcmp(command,"dmesg")){darwin_print_logs(&observer,NULL);continue;}if(!strcmp(command,"log")&&arg1&&!strcmp(arg1,"show")){char*filter=NULL;if(arg2&&!strcmp(arg2,"--predicate"))filter=next_token(&cursor);else if(arg2&&!strcmp(arg2,"--last"))next_token(&cursor);darwin_print_logs(&observer,filter);continue;}if(!strcmp(command,"spawn")&&arg1){printf("spawned pid %d\n",darwin_spawn(&observer,arg1));continue;}if(!strcmp(command,"kill")&&arg1){puts(darwin_kill(&observer,atoi(arg1))?"kill: no such process":"process terminated");continue;}if(!strcmp(command,"hostname")){puts(darwin_adapter_hostname());continue;}if(!strcmp(command,"pwd")){puts(darwin_adapter_cwd());continue;}if(!strcmp(command,"whoami")){puts("root");continue;}if(!strcmp(command,"ls")){darwin_adapter_list(arg1?arg1:".");continue;}puts("darwin-shell: command not found");}return 0;}
